inline constexpr std::string_view updated_sha = "a2e8e57c86ea60f12de1fa628f8db12014eb296fb259449ea688df9c7ba1497a";
inline constexpr std::string_view hotfix_sha = "4f6596b08bb5bc7fe4150cf5b9f71d7bae87eea02d66627c03a5e05ffe84ea62";
enum class EngineProfile { previous, october_update, october_hotfix };
// Selected once by bootstrap, before publishing any engine hook.
inline EngineProfile engine_profile=EngineProfile::previous;
inline bool known_build(std::string_view sha) noexcept { return sha==tested_sha || sha==updated_sha || sha==hotfix_sha; }
inline void select_profile(std::string_view sha) noexcept {
    engine_profile=sha==hotfix_sha?EngineProfile::october_hotfix:
        sha==updated_sha?EngineProfile::october_update:EngineProfile::previous;
}

struct EngineAddress {
    uintptr_t previous, current;
    std::array<unsigned char,32> prefix;
};
