inline const EngineAddress* mapped_address(uintptr_t previous) noexcept {
    if(engine_profile==EngineProfile::october_hotfix) {
        for(const auto& entry:october_hotfix_addresses) if(entry.previous==previous) return &entry;
    } else {
        for(const auto& entry:october_addresses) if(entry.previous==previous) return &entry;
    }
    return nullptr;
}
inline uintptr_t address(uintptr_t image,uintptr_t previous) noexcept {
    if(!image) return 0;
    if(engine_profile==EngineProfile::previous) return image+previous;
    const auto* entry=mapped_address(previous);
    return entry?image+entry->current:0;
}
inline std::string_view ui_document_sha() noexcept {
    return engine_profile!=EngineProfile::previous
        ? "2a56b5e655746d09f80b592b9e19d787eaccf72778a3df90b7773a564ecad527"
        : "5d236f36c75f1765c9c8e454392ac9210dd37c8e97fd98c39deebd5b5d8f15c7";
}
